        if (!rst_n) begin
            rd_grant_r <= 2'd0;
            rd_locked  <= 1'b0;
        end else if (!rd_locked) begin
            if (|rd_req) begin
                rd_grant_r <= rd_sel;
                rd_locked  <= 1'b1;
            end
