    wire [1:0] wr_sel = wr_req[0] ? 2'd0 :
                        wr_req[1] ? 2'd1 :
                        wr_req[2] ? 2'd2 : 2'd3;
    wire [1:0] wr_grant = wr_locked ? wr_grant_r : wr_sel;

